import React, { useEffect, useState } from 'react';
import { generateKeys, encryptMessage, decryptMessage } from '../utils/crypto';

const Chat = () => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [ws, setWs] = useState(null);
  const [keys, setKeys] = useState({});

  useEffect(() => {
    const initChat = async () => {
      const socket = new WebSocket('ws://localhost:8080');
      setWs(socket);

      const { privateKey, publicKey } = await generateKeys();
      setKeys({ privateKey, publicKey });

      socket.onopen = () => {
        console.log('WebSocket connected');
        socket.send(JSON.stringify({ type: 'key_exchange', publicKey }))
      };


      // Обрабатываем входящие сообщения
      socket.onmessage = async (event) => {
        const data = JSON.parse(event.data);
        console.log('Received WebSocket message:', data); // Логируем полученное сообщение
        if (data.type === 'key_exchange') {
          console.log(`Получен публичный ключ c сервера: ${data.publicKey}`);
          setKeys((prevKeys) => ({ ...prevKeys, recipientPublicKey: data.publicKey }));
        } else if (data.type === 'message') {
          try {
            // Расшифровываем сообщение, используя замыкание с privateKey
            const decryptedMessage = await decryptMessage(data.message, privateKey);
            setMessages((prev) => [...prev, { userId: data.userId, text: decryptedMessage }])
          } catch (err) {
            console.error('Ошибка расшифровки сообщения:', err);
          }
        }
      };

      socket.onerror = (err) => {
        console.error('WebSocket error:', err);
      };

      socket.onclose = () => {
        console.log('WebSocket connection closed');
      };
    };

    initChat();
  }, []); // Зависимость пустая, потому что privateKey используется через замыкание

  const sendMessage = async (message) => {
    try {
      // Проверяем наличие WebSocket соединения и публичного ключа сервера
      if (!ws || ws.readyState !== WebSocket.OPEN) {
        console.error('WebSocket is not connected');
        return;
      }
      if (!keys.recipientPublicKey) {
        console.error("Recipient's public key is missing");
        return;
      }

      // Шифруем сообщение
      const encryptedMessage = await encryptMessage(message, keys.recipientPublicKey);

      // Отправляем зашифрованное сообщение на сервер
      ws.send(
        JSON.stringify({
          type: 'message', // Сервер ожидает тип "message"
          encryptedMessage,
        })
      );

      console.log('Encrypted message sent:', encryptedMessage);

      // Добавляем сообщение в локальный чат (отправитель)
      setMessages((prev) => [...prev, { userId: 'You', text: message }]);
      setInput('');
    } catch (err) {
      console.error('Failed to send message:', err);
    }
  };



  return (
    <div>
      <h1>Anonymous Chat</h1>
      {!keys.recipientPublicKey && (
        <p style={{ color: 'red' }}>Waiting for recipient's public key...</p>
      )}
      <div>
        {messages.map((msg, index) => (
          <p key={index}>
            <strong>{msg.userId}:</strong> {msg.text}
          </p>
        ))}
      </div>
      <input
        type="text"
        value={input}
        onChange={(e) => setInput(e.target.value)}
        placeholder="Type your message..."
      />
      <button
        onClick={() => sendMessage(input, keys.recipientPublicKey)}
        disabled={!keys.recipientPublicKey}
      >
        Send
      </button>
    </div>
  );
};

export default Chat;
